def stair_ways(n: int, broken: list[int]) -> int:
    MOD = 1000000007
    broken_set = set(broken)
    ways = [0] * (n + 1)
    ways[0] = 1
    for i in range(1, n + 1):
        if i in broken_set:
            ways[i] = 0
        else:
            total = ways[i - 1]
            if i >= 2:
                total += ways[i - 2]
            ways[i] = total % MOD
    return ways[n]
```

