MOD = 1000000007

def stair_ways(n: int, broken: list[int]) -> int:
    broken_set = set(broken)
    dp = [0] * (n + 1)
    dp[0] = 1  # start position
    for i in range(1, n + 1):
        if i in broken_set:
            dp[i] = 0
        else:
            ways = 0
            if i - 1 >= 0:
                ways += dp[i - 1]
            if i - 2 >= 0:
                ways += dp[i - 2]
            dp[i] = ways % MOD
    return dp[n]
