def rle_decode(s: str) -> str:
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i].isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            count = int(s[i:j])
            if j < n:
                ch = s[j]
                result.append(ch * count)
                i = j + 1
            else:
                i = j
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)
