def grid_islands(grid: list[str]) -> list[int]:
    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0])
    board = [list(row) for row in grid]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    islands = []
    for i in range(rows):
        for j in range(cols):
            if board[i][j] == '#':
                stack = [(i, j)]
                size = 0
                while stack:
                    x, y = stack.pop()
                    if 0 <= x < rows and 0 <= y < cols and board[x][y] == '#':
                        board[x][y] = '.'  # mark visited
                        size += 1
                        for dx, dy in dirs:
                            nx, ny = x + dx, y + dy
                            stack.append((nx, ny))
                islands.append(size)
    islands.sort(reverse=True)
    return islands
```

