def next_bus(times: list[str], now: str) -> str:
    def to_min(t: str) -> int:
        h, m = map(int, t.split(":"))
        return h * 60 + m
    def to_str(m: int) -> str:
        h = m // 60
        m = m % 60
        return f"{h:02d}:{m:02d}"
    now_min = to_min(now)
    times_min = [to_min(t) for t in times]
    future = [t for t in times_min if t >= now_min]
    if future:
        result = min(future)
    else:
        result = min(times_min)
    return to_str(result)
```

