def bracket_depth(s: str) -> int:
    opening = "({["
    closing = ")}]"
    match = {')': '(', ']': '[', '}': '{'}
    stack = []
    max_depth = 0
    current = 0
    for ch in s:
        if ch in opening:
            stack.append(ch)
            current += 1
            if current > max_depth:
                max_depth = current
        elif ch in closing:
            if not stack:
                return -1
            if stack[-1] != match[ch]:
                return -1
            stack.pop()
            current -= 1
    if stack:
        return -1
    return max_depth
```

