def bracket_depth(s: str) -> int:
    opening = {'(', '[', '{'}
    closing_to_open = {')': '(', ']': '[', '}': '{'}
    stack = []
    max_depth = 0
    for ch in s:
        if ch in opening:
            stack.append(ch)
            if len(stack) > max_depth:
                max_depth = len(stack)
        elif ch in closing_to_open:
            if not stack or stack[-1] != closing_to_open[ch]:
                return -1
            stack.pop()
    if stack:
        return -1
    return max_depth
