def bracket_depth(s: str) -> int:
    opening = "({["
    closing = ")}]"
    match = {')': '(', ']': '[', '}': '{'}
    stack = []
    max_depth = 0
    for ch in s:
        if ch in opening:
            stack.append(ch)
            max_depth = max(max_depth, len(stack))
        elif ch in closing:
            if not stack:
                return -1
            if stack[-1] != match[ch]:
                return -1
            stack.pop()
    if stack:
        return -1
    return max_depth
